using MeetingDirectory;
int count=0;
void Check(bool condition,string description) {if(!condition)throw new Exception(description);count++;Console.WriteLine("PASS "+description);}
void Reject(Action action,string description){try{action();}catch{Check(true,description);return;}throw new Exception(description);}
var eastern=TimeZoneInfo.FindSystemTimeZoneById(OperatingSystem.IsWindows()?"Eastern Standard Time":"America/New_York");
var sample=new Meeting{Name="Test call",Link="https://zoom.us/j/123456789",ZoneId=eastern.Id,Start=new DateOnly(2026,1,1),Time=new TimeOnly(19,0),Pattern=Pattern.MonthlyWeekday,MonthWeekday=DayOfWeek.Tuesday,Ordinals=[1,3]};
Check(Occurrences.Matches(sample,new(2026,11,3)),"First Tuesday");
Check(Occurrences.Matches(sample,new(2026,11,17)),"Third Tuesday");
Check(!Occurrences.Matches(sample,new(2026,11,10)),"Exclude second Tuesday");
Check(Occurrences.Matches(sample with{Ordinals=[-1],MonthWeekday=DayOfWeek.Friday},new(2026,11,27)),"Last Friday");
Check(!Occurrences.Matches(sample with{Ordinals=[5]},new(2026,11,24)),"No fifth Tuesday in November");
var date=sample with{Pattern=Pattern.MonthlyDate,MonthDay=31};
Check(Occurrences.Next(date,new DateTimeOffset(2026,4,1,0,0,0,TimeSpan.Zero))==new DateTimeOffset(2026,5,31,23,0,0,TimeSpan.Zero),"Skip month missing day 31");
Check(Occurrences.ToInstant(new DateTime(2026,3,8,2,30,0),eastern)==null,"Spring gap has no instant");
Check(Occurrences.ToInstant(new DateTime(2026,11,1,1,30,0),eastern)==new DateTimeOffset(2026,11,1,5,30,0,TimeSpan.Zero),"Fall overlap chooses earlier occurrence");
var daily=sample with{Pattern=Pattern.Daily,Time=new TimeOnly(2,30)};
Check(Occurrences.Next(daily,new DateTimeOffset(2026,3,8,5,0,0,TimeSpan.Zero))==new DateTimeOffset(2026,3,9,6,30,0,TimeSpan.Zero),"Daily schedule skips nonexistent spring time");
var once=sample with{Pattern=Pattern.Once,Start=new(2026,11,3)};
var instant=new DateTimeOffset(2026,11,4,0,0,0,TimeSpan.Zero);
Check(Occurrences.Next(once,instant)==instant,"Include exact start");
Check(Occurrences.Next(once,instant.AddSeconds(1))==null,"Exclude past one-time meeting");
var weekly=sample with{Pattern=Pattern.Weekly,Days=[DayOfWeek.Monday,DayOfWeek.Wednesday],End=new(2026,11,2)};
Check(Occurrences.Next(weekly,new DateTimeOffset(2026,11,3,6,0,0,TimeSpan.Zero))==null,"Respect recurrence end date");
Reject(()=>Meeting.ValidateLink("https://zoom.us.evil.example/j/123","Zoom"),"Reject lookalike host");
Reject(()=>Meeting.ValidateLink("file:///C:/test.exe","Zoom"),"Reject local file launch");
Reject(()=>Meeting.ValidateLink("https://zoom.us@evil.example/j/123","Zoom"),"Reject deceptive userinfo");
Reject(()=>Meeting.ValidateLink("https://teams.microsoft.com/l/meetup-join/abc","Zoom"),"Reject platform mismatch");
Meeting.ValidateLink("https://teams.microsoft.com/l/meetup-join/abc","Teams");count++;
Reject(()=>(weekly with{Days=[]}).Validate(),"Require weekly weekdays");
var folder=Path.Combine(Path.GetTempPath(),"MeetingDirectory-checks-"+Guid.NewGuid());Directory.CreateDirectory(folder);
try {
    var store=new Store(Path.Combine(folder,"meetings.json"));store.Save([sample]);
    Check(store.Load().Single().Name==sample.Name,"JSON round trip");
    store.Save([sample with{Name="Changed"}]);
    Check(Store.Read(store.PathName+".previous").Single().Name==sample.Name,"Retain previous save");
    Reject(()=>Store.Parse("[{]"),"Reject malformed backup");
    Reject(()=>Store.Parse(System.Text.Json.JsonSerializer.Serialize(new[]{sample,sample})),"Reject duplicate identifiers");
    Reject(()=>store.Save([sample with{Link="invalid"}]),"Reject invalid save");
    Check(store.Load().Single().Name=="Changed","Failed save preserves data");
}finally{Directory.Delete(folder,true);}
// Version 0.2: exceptions, Today ranges, reminders, invitation parsing and merge safety.
var dayStart=new DateTimeOffset(2026,11,3,5,0,0,TimeSpan.Zero);
var dayEnd=dayStart.AddDays(1);
var baseDaily=sample with{Pattern=Pattern.Daily,Time=new TimeOnly(10,0)};
var skip=baseDaily with{Exceptions=[new(){OriginalDate=new(2026,11,3),Skip=true}]};
skip.Validate();
Check(Occurrences.Between(skip,dayStart,dayEnd).Count==0,"Skipped occurrence absent from Today");
Check(Occurrences.Next(skip,dayStart)==new DateTimeOffset(2026,11,4,15,0,0,TimeSpan.Zero),"Skipped occurrence absent from Next");
var moved=baseDaily with{Exceptions=[new(){OriginalDate=new(2026,11,2),Skip=false,NewLocalStart=new DateTime(2026,11,3,8,0,0)}]};
moved.Validate();
var today=Occurrences.Between(moved,dayStart,dayEnd);
Check(today.Count==2 && today[0].OriginalDate==new DateOnly(2026,11,2),"Moved occurrence comes from a different original day");
Check(today[0].At==new DateTimeOffset(2026,11,3,13,0,0,TimeSpan.Zero),"Moved time uses meeting time zone");
Check(Occurrences.Between(moved,dayStart.AddDays(-1),dayStart).Count==0,"Moved occurrence removed from original date");
Check(Occurrences.Between(baseDaily,dayStart,dayEnd).Single().At<dayStart.AddHours(18),"Today retains earlier start independently of current time");
var movedOnce=once with{Exceptions=[new(){OriginalDate=once.Start,Skip=false,NewLocalStart=new DateTime(2026,11,7,12,0,0)}]};
Check(Occurrences.Next(movedOnce,dayStart)==new DateTimeOffset(2026,11,7,17,0,0,TimeSpan.Zero),"Moved one-time meeting used by Next");
Reject(()=>(sample with{Exceptions=[new(){OriginalDate=new(2026,11,4)}]}).Validate(),"Reject exception outside monthly schedule");
Reject(()=>(baseDaily with{Exceptions=[new(){OriginalDate=new(2026,11,3)},new(){OriginalDate=new(2026,11,3)}]}).Validate(),"Reject duplicate exceptions");
Reject(()=>(baseDaily with{Exceptions=[new(){OriginalDate=new(2026,3,8),Skip=false,NewLocalStart=new DateTime(2026,3,8,2,30,0)}]}).Validate(),"Reject moved occurrence in DST gap");
var reminderMeeting=baseDaily with{ReminderMinutes=10};
var now=new DateTimeOffset(2026,11,3,14,50,0,TimeSpan.Zero);
var delivered=new HashSet<string>();
var due=DirectoryFeatures.Due([reminderMeeting],now,delivered);
Check(due.Count==1,"Reminder due ten minutes before");
Check(DirectoryFeatures.Due([reminderMeeting],now.AddSeconds(-1),delivered).Count==0,"Reminder not early");
delivered.Add(due[0].Key);
Check(DirectoryFeatures.Due([reminderMeeting],now,delivered).Count==0,"Delivered reminder does not repeat");
Check(DirectoryFeatures.Due([baseDaily],now,new HashSet<string>()).Count==0,"Off produces no reminders");
Check(DirectoryFeatures.Due([reminderMeeting with{Exceptions=skip.Exceptions}],now,new HashSet<string>()).Count==0,"No reminder for skipped occurrence");
Check(DirectoryFeatures.Due([baseDaily with{ReminderMinutes=0}],now.AddMinutes(10).AddSeconds(10),new HashSet<string>()).Count==1,"At-start reminder tolerates timer delay");
Check(DirectoryFeatures.Due([reminderMeeting],now.AddMinutes(11),new HashSet<string>()).Count==0,"No stale reminder for past meeting");
var merge=DirectoryFeatures.Merge([sample],[sample with{Name="Do not overwrite"},baseDaily with{Id=Guid.NewGuid(),Name="New imported",Favorite=true,ReminderMinutes=10,Category="Community"}]);
Check(merge.Added==1 && merge.Skipped==1 && merge.Meetings[0].Name==sample.Name,"Import keeps existing ID and adds new entry");
Check(!merge.Meetings[1].Favorite && merge.Meetings[1].ReminderMinutes==null && merge.Meetings[1].Category=="Community","Import keeps category and disables personal settings");
Check(DirectoryFeatures.Merge([sample],[sample with{Id=Guid.NewGuid()}]).Skipped==1,"Import skips separately identified duplicate schedule");
var invite="Topic: Community chat\nTime: Nov 3, 2026 07:00 PM Eastern Time\nJoin Zoom Meeting\nhttps://zoom.us/j/123456789?pwd=abc\nMeeting ID: 123 456 789\nPasscode: hello\nEvery day";
var links=Invitations.Links(invite);
Check(links.Length==1,"Invitation detects direct link");
var draft=Invitations.Parse(invite,links[0]);
Check(draft.Meeting.Name=="Community chat" && draft.Meeting.Platform=="Zoom" && draft.Meeting.Passcode=="hello","Invitation extracts name, platform and passcode");
Check(draft.Meeting.Start==new DateOnly(2026,11,3) && draft.Meeting.Time==new TimeOnly(19,0) && draft.Meeting.Pattern==Pattern.Daily,"Invitation extracts date, AM/PM time and daily recurrence");
Check(TimeZoneInfo.FindSystemTimeZoneById(draft.Meeting.ZoneId).GetUtcOffset(new DateTime(2026,11,3))==TimeSpan.FromHours(-5),"Invitation recognizes Eastern zone");
Check(draft.Meeting.Notes==invite,"Invitation preserves original in notes");
Check(Invitations.Links("https://zoom.us.evil.example/j/1 https://evil.example").Length==0,"Invitation rejects spoofed and unrelated links");
Check(Invitations.Links("https://teams.microsoft.com/l/meetup-join/a https://zoom.us/j/1").Length==2,"Invitation offers multiple meeting links");
var bare=Invitations.Parse("https://zoom.us/j/123456789","https://zoom.us/j/123456789");
Check(!bare.Detected.Contains("Time") && !bare.Detected.Contains("Start date") && bare.Meeting.MeetingId=="123456789","Bare invite leaves unknown date and time for review");
var oldJson="[{\"Id\":\"bdc0af7f-5561-4ad0-aecd-958b4a1bf77b\",\"Name\":\"Old meeting\",\"Platform\":\"Zoom\",\"Link\":\"https://zoom.us/j/123\",\"ZoneId\":\"UTC\",\"Start\":\"2026-11-02\",\"Time\":\"12:00:00\",\"Pattern\":1}]";
var old=Store.Parse(oldJson).Single();
Check(!old.Favorite && old.Category=="" && old.ReminderMinutes==null && old.Exceptions.Length==0,"Legacy directory loads with safe defaults");
var rich=moved with{Favorite=true,Category="Classes",ReminderMinutes=15};
var round=Store.Parse(System.Text.Json.JsonSerializer.Serialize(new[]{rich})).Single();
Check(round.Favorite && round.Category=="Classes" && round.ReminderMinutes==15 && round.Exceptions.Single().NewLocalStart==rich.Exceptions.Single().NewLocalStart,"New settings and exceptions survive backup round trip");
var farMoved=once with{Exceptions=[new(){OriginalDate=once.Start,Skip=false,NewLocalStart=new DateTime(2030,11,3,12,0,0)}]};
Check(Occurrences.Next(farMoved,dayStart)==new DateTimeOffset(2030,11,3,17,0,0,TimeSpan.Zero),"Next finds distant rescheduled one-time meeting");
var sameInstant=baseDaily with{Exceptions=[new(){OriginalDate=new(2026,11,2),Skip=false,NewLocalStart=new DateTime(2026,11,3,10,0,0)}],ReminderMinutes=10};
var simultaneous=DirectoryFeatures.Due([sameInstant],now,new HashSet<string>());
Check(simultaneous.Count==2 && simultaneous[0].Key!=simultaneous[1].Key,"Same-time moved occurrences keep separate reminder identities");
var fallFrom=Occurrences.ToInstant(new DateTime(2026,11,1),eastern)!.Value;
var fallUntil=Occurrences.ToInstant(new DateTime(2026,11,2),eastern)!.Value;
Check((fallUntil-fallFrom).TotalHours==25 && Occurrences.Between(baseDaily,fallFrom,fallUntil).Count==1,"Today handles 25-hour local day");
var springFrom=Occurrences.ToInstant(new DateTime(2026,3,8),eastern)!.Value;
var springUntil=Occurrences.ToInstant(new DateTime(2026,3,9),eastern)!.Value;
Check((springUntil-springFrom).TotalHours==23 && Occurrences.Between(baseDaily,springFrom,springUntil).Count==1,"Today handles 23-hour local day");
Reject(()=>(baseDaily with{ReminderMinutes=-1}).Validate(),"Reject invalid reminder interval");
Reject(()=>(baseDaily with{Category=null!}).Validate(),"Reject malformed category");
Check(DirectoryFeatures.Merge([sample],[sample with{Id=Guid.NewGuid(),Name="Different call using same link"}]).Added==1,"Shared link may serve distinct meeting names");
Console.WriteLine($"{count} checks passed.");
